assertionResults.fullName:
generated command forwards exact payload and security headers: (studentId, createManagerPaymentDto, options) => {
    const getHeaders = (h) => {
        if (!h)
            return {};
        if (h instanceof Headers)
            return Object.fromEntries(h.entries());
        if (Symbol.iterator in h) {
            return Object.fromEntries(Array.from(h, (entry) => Array.from(entry)));
        }
        const headers = {};
        for (const [name, value] of Object.entries(h)) {
            if (value !== undefined)
                headers[name] = value;
        }
        return headers;
    };
    return schoolFetch(getCreateManagerPaymentUrl(studentId), {
        ...options,
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
        body: JSON.stringify(createManagerPaymentDto)
    });
}

